const jwt = require('jsonwebtoken');
const bcrypt = require('bcryptjs');
const zxcvbn = require('zxcvbn');

const app = express();
const PORT = 3000;

// Middleware
app.use(bodyParser.json());
app.use(express.static('public'));

// In-memory database (for demonstration purposes)
const users = [];

// Password strength validation function
function validatePassword(password) {
  const result = zxcvbn(password);
  // Set a minimum password strength requirement (e.g., 3 out of 5)
  if (result.score < 3) {
    return 'Password is too weak. Please choose a stronger password.';
  }

  // Check for common weak passwords
  const weakPasswords = ['password', '123456', 'qwerty', 'admin', 'letmein'];
  if (weakPasswords.includes(password.toLowerCase())) {
    return 'Password is too common. Please choose a different one.';
  }

  // Check for minimum length
  if (password.length < 8) {
    return 'Password must be at least 8 characters long.';
  }

  // Check for at least one uppercase letter
  if (!/[A-Z]/.test(password)) {
    return 'Password must contain at least one uppercase letter.';
  }

  // Check for at least one lowercase letter
  if (!/[a-z]/.test(password)) {
    return 'Password must contain at least one lowercase letter.';
  }

  // Check for at least one number
  if (!/\d/.test(password)) {
    return 'Password must contain at least one number.';
  }

  // Check for special characters
  if (!/[!@#$%^&*(),.?":{}|<>]/.test(password)) {
    return 'Password must contain at least one special character.';
  }

  return null; // No validation errors
}

// Register route
app.post('/register', (req, res) => {
  const { username, email, password } = req.body;

  // Validate required fields
  if (!username || !email || !password) {
    return res.status(400).json({ error: 'All fields are required.' });
  }

  // Validate email format
  if (!/^\w+@[a-zA-Z_]+?\.[a-zA-Z]{2,3}$/.test(email)) {
    return res.status(400).json({ error: 'Invalid email format.' });
  }

  // Validate password strength
  const passwordError = validatePassword(password);
  if (passwordError) {
    return res.status(400).json({ error: passwordError });
  }

  // Check if user already exists
  const existingUser = users.find(user => user.email === email);
  if (existingUser) {
    return res.status(400).json({ error: 'User with this email already exists.' });
  }

  // Hash password
  const hashedPassword = bcrypt.hashSync(password, 10);

  // Create new user
  const newUser = {
    id: Date.now(),
    username,
    email,
    password: hashedPassword,
    role: 'user' // Default role
  };

  users.push(newUser);

  res.status(201).json({ message: 'User registered successfully.' });
});

// Login route
app.post('/login', (req, res) => {
  const { email, password } = req.body;

  // Validate required fields
  if (!email || !password) {
    return res.status(400).json({ error: 'Email and password are required.' });
  }

  // Find user by email
  const user = users.find(user => user.email === email);
  if (!user) {
    return res.status(401).json({ error: 'Invalid email or password.' });
  }

  // Verify password
  const isPasswordValid = bcrypt.compareSync(password, user.password);
  if (!isPasswordValid) {
    return res.status(401).json({ error: 'Invalid email or password.' });
  }

  // Create JWT token
  const token = jwt.sign({ userId: user.id, role: user.role }, 'your-secret-key', { expiresIn: '1h' });

  res.json({ token });
});

// Protected route (example)
app.get('/protected', (req, res) => {
  // Verify JWT token
  const token = req.headers['authorization'];
  if (!token) {
    return res.status(401).json({ error: 'Access denied.' });
  }

  try {
    const decoded = jwt.verify(token, 'your-secret-key');
    res.json({ message: `Welcome, ${decoded.userId}!` });
  } catch (err) {
    res.status(400).json({ error: 'Invalid token.' });
  }
});

// Start server
app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
